package com.example.resource;

import com.example.Consentimiento;
import com.example.repository.ConsentimientoRepository;
import io.quarkus.panache.common.Page;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;
import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import jakarta.ws.rs.*;
import jakarta.ws.rs.core.MediaType;
import jakarta.ws.rs.core.Response;
import java.net.URI;
import java.util.List;
import java.util.UUID;

@Path("/api/consentimiento")
@Produces(MediaType.APPLICATION_JSON)
@Consumes(MediaType.APPLICATION_JSON)
public class ConsentimientoResource {

    @Inject
    ConsentimientoRepository repository;

    @GET
    public List<Consentimiento> list(
        @QueryParam("page") @DefaultValue("0") int page,
        @QueryParam("size") @DefaultValue("20") int size
    ) {
        if (size <= 0) {
            return repository.listAll();
        }
        int safePage = Math.max(page, 0);
        int safeSize = Math.min(size, 100);
        return repository.findAll().page(Page.of(safePage, safeSize)).list();
    }

    @GET
    @Path("/{id}")
    public Response getById(@PathParam("id") Long id) {
        return repository.findByIdOptional(id)
            .map(entity -> Response.ok(entity).build())
            .orElseGet(() -> Response.status(Response.Status.NOT_FOUND).build());
    }

    @POST
    @Transactional
    public Response create(@Valid @NotNull Consentimiento entity) {
        entity.setId(null);
        repository.persist(entity);
        return Response.created(URI.create("/api/consentimiento/" + entity.getId())).entity(entity).build();
    }

    @PUT
    @Path("/{id}")
    @Transactional
    public Response update(@PathParam("id") Long id, @Valid @NotNull Consentimiento updated) {
        Consentimiento existing = repository.findById(id);
        if (existing == null) {
            return Response.status(Response.Status.NOT_FOUND).build();
        }
        if (updated.getEstado() != null) {
            existing.setEstado(updated.getEstado());
        }
        if (updated.getExpiracion() != null) {
            existing.setExpiracion(updated.getExpiracion());
        }
        if (updated.getOtp() != null) {
            existing.setOtp(updated.getOtp());
        }
        if (updated.getIntentosFallidos() != null) {
            existing.setIntentosFallidos(updated.getIntentosFallidos());
        }
        return Response.ok(existing).build();
    }

    @DELETE
    @Path("/{id}")
    @Transactional
    public Response delete(@PathParam("id") Long id) {
        boolean deleted = repository.deleteById(id);
        if (!deleted) {
            return Response.status(Response.Status.NOT_FOUND).build();
        }
        return Response.status(Response.Status.NO_CONTENT).build();
    }
}

