import io.quarkus.test.junit.QuarkusTest;
import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import static io.restassured.RestAssured.given;
import static org.hamcrest.CoreMatchers.*;

@QuarkusTest
public class ConsentimientoResourceTest {

    @Test
    public void testListEndpoint() {
        given()
            .when().get("/api/consentimiento")
            .then()
            .statusCode(200);
    }

    @Test
    public void testGetNotFoundEndpoint() {
        given()
            .when().get("/api/consentimiento/999999")
            .then()
            .statusCode(404);
    }

    @Test
    public void testCreateGetUpdateAndDeleteLifecycle() {
        Object createdId = given()
            .contentType(ContentType.JSON)
            .body("{\"estado\": \"sample_estado_3\", \"expiracion\": \"2026-10-16T12:00:00Z\", \"otp\": \"sample_otp_3\", \"intentosFallidos\": 3}")
            .when().post("/api/consentimiento")
            .then()
            .statusCode(201)
            .body("id", notNullValue())
            .extract().path("id");

        given()
            .when().get("/api/consentimiento/" + createdId)
            .then()
            .statusCode(200)
            .body("id", notNullValue());

        given()
            .contentType(ContentType.JSON)
            .body("{\"estado\": \"sample_estado_4\", \"expiracion\": \"2026-10-17T12:00:00Z\", \"otp\": \"sample_otp_4\", \"intentosFallidos\": 4}")
            .when().put("/api/consentimiento/" + createdId)
            .then()
            .statusCode(200)
            .body("estado", equalTo("sample_estado_4"));

        given()
            .when().delete("/api/consentimiento/" + createdId)
            .then()
            .statusCode(204);

        given()
            .when().get("/api/consentimiento/" + createdId)
            .then()
            .statusCode(404);
    }

    @Test
    public void testUpdateNotFoundEndpoint() {
        given()
            .contentType(ContentType.JSON)
            .body("{\"estado\": \"sample_estado_4\", \"expiracion\": \"2026-10-17T12:00:00Z\", \"otp\": \"sample_otp_4\", \"intentosFallidos\": 4}")
            .when().put("/api/consentimiento/999999")
            .then()
            .statusCode(404);
    }

    @Test
    public void testDeleteNotFoundEndpoint() {
        given()
            .when().delete("/api/consentimiento/999999")
            .then()
            .statusCode(404);
    }
}

