import com.example.Consentimiento;
import io.quarkus.test.junit.QuarkusTest;
import jakarta.inject.Inject;
import jakarta.transaction.Transactional;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.LocalDate;
import java.time.LocalDateTime;
import java.time.Instant;
import java.util.UUID;

@QuarkusTest
public class ConsentimientoRepositoryTest {

    @Inject
    ConsentimientoRepository repository;

    @Test
    @Transactional
    public void testPersistAndFind() {
        repository.deleteAll();
        Consentimiento entity = new Consentimiento();
        entity.setEstado("Sample");
        entity.setExpiracion(new Timestamp(System.currentTimeMillis()));
        entity.setOtp("Sample");
        entity.setIntentosFallidos(1);

        repository.persist(entity);
        assertNotNull(entity.getId());
        assertTrue(repository.findByIdOptional(entity.getId()).isPresent());
        assertNotNull(repository.findById(entity.getId()));
        repository.deleteById(entity.getId());
    }

    @Test
    @Transactional
    public void testDelete() {
        repository.deleteAll();
        Consentimiento entity = new Consentimiento();
        entity.setEstado("Sample_2");
        entity.setExpiracion(new Timestamp(System.currentTimeMillis()));
        entity.setOtp("Sample_2");
        entity.setIntentosFallidos(2);

        repository.persist(entity);
        Long id = entity.getId();
        assertNotNull(id);

        boolean deleted = repository.deleteById(id);
        assertTrue(deleted);
        assertTrue(repository.findByIdOptional(id).isEmpty());
    }
}

